import { CapScheduleDB } from './db.js';

const db=new CapScheduleDB();
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const pad=n=>String(n).padStart(2,'0');
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const deepClone=o=>JSON.parse(JSON.stringify(o));
const today=()=>new Date();
const monthLabel=d=>d.toLocaleDateString(undefined,{month:'long',year:'numeric'});
const dateISO=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const localDateTimeValue=v=>{if(!v)return'';const d=new Date(v);return `${dateISO(d)}T${pad(d.getHours())}:${pad(d.getMinutes())}`};
const toMinutes=t=>{if(!t)return 0;const [h,m]=String(t).slice(0,5).split(':').map(Number);return h*60+m};
const fromMinutes=m=>`${pad(Math.floor(m/60)%24)}:${pad((m%60+60)%60)}`;
const snap5=m=>Math.round(m/5)*5;
const niceTime=t=>{if(!t)return'';const [h,m]=String(t).slice(0,5).split(':').map(Number);return new Date(2000,0,1,h,m).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})};
const fmtDate=s=>new Date(`${String(s).slice(0,10)}T12:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'});
const fmtDateTime=v=>new Date(v).toLocaleString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});
const fmtDateShort=v=>new Date(v).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
const minutesBetween=(a,b)=>Math.max(0,Math.round((new Date(b)-new Date(a))/60000));
const uid=p=>`${p}-${crypto.randomUUID?.()||Math.random().toString(36).slice(2)}`;

const state={
  units:[],user:null,demoMode:false,
  publicDate:new Date(today().getFullYear(),today().getMonth(),1),publicLookup:null,publicRows:[],
  planDate:new Date(today().getFullYear(),today().getMonth(),1),planning:null,planLookup:null,selectedMeetingId:null,
  specialList:[],specialPlanning:null,specialLookup:null,selectedSpecialDate:null,
  installPrompt:null,adminPage:'units'
};

function toast(message,type=''){const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=message;$('#toastContainer').appendChild(e);setTimeout(()=>e.remove(),4300)}
function setBusy(el,busy,label='Working…'){if(!el)return;if(busy){el.dataset.old=el.textContent;el.disabled=true;el.textContent=label}else{el.disabled=false;el.textContent=el.dataset.old||el.textContent}}
function unitName(id){return state.units.find(u=>u.id===id)?.name||'Unknown Unit'}
function lookupName(list,id){const x=list?.find(v=>v.id===id);return x?.name||x?.title||''}
function editableUnits(program=null){if(!state.user)return[];if(state.user.isAppAdmin)return state.units;return state.units.filter(u=>state.user.permissions?.some(p=>p.unit_id===u.id&&(program?(program==='cadet'?p.can_edit_cadet:p.can_edit_senior):(p.can_edit_cadet||p.can_edit_senior))))}
function adminUnits(){if(!state.user)return[];if(state.user.isAppAdmin)return state.units;return state.units.filter(u=>state.user.permissions?.some(p=>p.unit_id===u.id&&p.is_unit_admin))}
function preferredUnit(units=state.units){const ids=units.map(u=>u.id);const account=state.user?.defaultUnitId;if(account&&ids.includes(account))return account;const local=localStorage.getItem('capSchedule.editorDefaultUnit');if(local&&ids.includes(local))return local;return units[0]?.id||''}
function selectedMeeting(){return state.planning?.version?.meetings?.find(m=>m.id===state.selectedMeetingId)||null}
function groupById(lookup,id){return lookup?.groups?.find(g=>g.id===id)}
function eventColor(event,lookup){const g=groupById(lookup,event.group_ids?.[0]);return g?.color||'#4f7ca7'}
function groupChips(ids,lookup){if(!ids?.length)return '<span class="group-chip" style="--chip-color:#7e8b99"><span class="group-dot"></span>Everyone</span>';return ids.map(id=>{const g=groupById(lookup,id);return g?`<span class="group-chip" style="--chip-color:${esc(g.color)}"><span class="group-dot"></span>${esc(g.name)}</span>`:''}).join('')}

function holidayLabel(iso){const d=new Date(`${iso}T12:00:00`),m=d.getMonth(),day=d.getDate();const fixed={'0-1':"New Year's Day",'6-4':'Independence Day','10-11':'Veterans Day','11-25':'Christmas Day'};return fixed[`${m}-${day}`]||''}

async function init(){
  bindGlobalUI();registerPWA();updateConnectionUI();
  const initResult=await db.init(async user=>{state.user=user;await refreshAuthUI()});
  state.demoMode=initResult.demoMode;state.user=initResult.userContext;
  try{state.units=await db.getUnits()}catch(err){toast(err.message,'warning');state.units=[]}
  populateUnitSelectors();restorePublicDefault();await refreshAuthUI();updateMonthButtons();
  await renderPublicSchedule();await renderSpecialActivities();await updateOfflineWorkUI();
  if(navigator.onLine)db.refreshOfflinePublicCache().catch(console.warn);
}

function bindGlobalUI(){
  $$('.tab').forEach(b=>b.addEventListener('click',()=>activateTab(b.dataset.tab)));
  document.addEventListener('click',e=>{if(e.target.closest('.close-dialog'))e.target.closest('dialog')?.close()});
  $('#loginButton').addEventListener('click',()=>$('#loginDialog').showModal());
  $('#loginForm').addEventListener('submit',handleLogin);
  $('#logoutButton').addEventListener('click',async()=>{await db.signOut();state.user=null;await refreshAuthUI();activateTab('schedule');toast('Logged out.')});
  $('#accountButton').addEventListener('click',openAccountDialog);$('#accountForm').addEventListener('submit',saveAccount);
  $('#syncButton').addEventListener('click',syncOfflineWork);

  $('#publicUnitSelect').addEventListener('change',async()=>{syncPublicDefaultCheckbox();await renderPublicSchedule()});
  $('#publicProgramSelect').addEventListener('change',async()=>{syncPublicDefaultCheckbox();await renderPublicSchedule()});
  $('#publicViewSelect').addEventListener('change',renderPublicRows);
  $('#saveDefaultSchedule').addEventListener('change',savePublicDefault);
  $('#publicPrevMonth').addEventListener('click',()=>shiftMonth('public',-1));$('#publicNextMonth').addEventListener('click',()=>shiftMonth('public',1));
  $('#publicCurrentMonth').addEventListener('click',()=>{state.publicDate=new Date(today().getFullYear(),today().getMonth(),1);updateMonthButtons();renderPublicSchedule()});
  $('#printScheduleButton').addEventListener('click',()=>window.print());

  $('#planPrevMonth').addEventListener('click',()=>shiftMonth('plan',-1));$('#planNextMonth').addEventListener('click',()=>shiftMonth('plan',1));
  $('#planCurrentMonth').addEventListener('click',()=>{state.planDate=new Date(today().getFullYear(),today().getMonth(),1);updateMonthButtons();loadPlanningMonth()});
  $('#planUnitSelect').addEventListener('change',()=>{syncPlanningDefaultCheckbox();loadPlanningMonth()});
  $('#planProgramSelect').addEventListener('change',()=>{populatePlanUnitSelector();loadPlanningMonth()});
  $('#planMeetingWeekday').addEventListener('change',changePlanningWeekday);$('#planZoomSelect').addEventListener('change',renderPlanner);
  $('#savePlanningDefault').addEventListener('change',savePlanningDefault);
  $('#publishButton').addEventListener('click',publishSchedule);$('#copyMonthButton').addEventListener('click',openCopyMonth);
  $('#meetingThemeSelect').addEventListener('change',saveMeetingHeader);$('#meetingUniformSelect').addEventListener('change',saveMeetingHeader);$('#meetingStartTime').addEventListener('change',saveMeetingHeader);$('#meetingEndTime').addEventListener('change',saveMeetingHeader);
  $('#cancelMeetingButton').addEventListener('click',toggleMeetingCancelled);$('#copyMeetingButton').addEventListener('click',openCopyMeeting);
  $('#copyMeetingForm').addEventListener('submit',copyMeeting);$('#copyMonthForm').addEventListener('submit',copyMonth);
  $('#addEventButton').addEventListener('click',()=>openEventDialog());$('#eventForm').addEventListener('submit',saveEventForm);$('#deleteEventButton').addEventListener('click',deleteWeeklyEvent);
  $('#activityLibraryButton').addEventListener('click',openActivityLibrary);$('#meetingTemplatesButton').addEventListener('click',openMeetingTemplates);$('#saveTemplateForm').addEventListener('submit',saveCurrentTemplate);

  $('#activityUnitFilter').addEventListener('change',renderSpecialActivities);$('#activityRangeFilter').addEventListener('change',renderSpecialActivities);
  $('#specialPlanUnitSelect').addEventListener('change',loadSpecialPlanningList);$('#specialPlanActivitySelect').addEventListener('change',loadSpecialPlanningActivity);$('#specialPlanZoomSelect').addEventListener('change',renderSpecialPlanner);
  $('#newSpecialActivityButton').addEventListener('click',()=>openSpecialActivityDialog());$('#editSpecialActivityButton').addEventListener('click',()=>state.specialPlanning&&openSpecialActivityDialog(state.specialPlanning.activity));
  $('#specialActivityForm').addEventListener('submit',saveSpecialActivityForm);$('#specialStart').addEventListener('change',ensureSpecialEnd);$('#specialEnd').addEventListener('change',ensureSpecialEnd);
  $('#addSpecialEventButton').addEventListener('click',()=>openSpecialEventDialog());$('#specialEventForm').addEventListener('submit',saveSpecialEventForm);$('#deleteSpecialEventButton').addEventListener('click',deleteSpecialEvent);
  $('#manageSpecialRoomsButton').addEventListener('click',openSpecialRooms);$('#specialRoomForm').addEventListener('submit',addSpecialRoom);$('#copyUnitRoomsButton').addEventListener('click',copyUnitRoomsToSpecial);$('#publishSpecialButton').addEventListener('click',publishSpecialActivity);

  $$('.admin-nav-item').forEach(b=>b.addEventListener('click',()=>activateAdminPage(b.dataset.adminPage)));
  window.addEventListener('online',async()=>{updateConnectionUI();try{await db.reconnect();await syncOfflineWork(true);await db.refreshOfflinePublicCache()}catch(err){console.warn(err)}});
  window.addEventListener('offline',()=>{updateConnectionUI();updateOfflineWorkUI()});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;$('#installButton').classList.remove('hidden')});
  window.addEventListener('appinstalled',()=>{state.installPrompt=null;$('#installButton').textContent='Installed';$('#installButton').disabled=true;toast('CAP Schedule installed.','success')});
  $('#installButton').addEventListener('click',installApp);
}

function activateTab(name){
  $$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));$$('.tab-panel').forEach(x=>x.classList.toggle('active',x.id===`${name}Tab`));
  if(name==='planning')loadPlanningMonth();if(name==='activities')renderSpecialActivities();if(name==='activityPlanning')loadSpecialPlanningList();if(name==='admin')renderAdmin();
}
async function handleLogin(e){e.preventDefault();const b=e.submitter;setBusy(b,true,'Logging in…');$('#loginError').textContent='';try{state.user=await db.signIn($('#loginEmail').value.trim(),$('#loginPassword').value);$('#loginDialog').close();await refreshAuthUI();toast('Logged in.','success')}catch(err){$('#loginError').textContent=err.message||String(err)}finally{setBusy(b,false)}}
async function refreshAuthUI(){
  $('#modeBadge').textContent=state.demoMode?'Demo Mode':'Supabase';$('#userLabel').textContent=state.user?.displayName||'';
  $('#loginButton').classList.toggle('hidden',!!state.user);$('#accountButton').classList.toggle('hidden',!state.user);$('#logoutButton').classList.toggle('hidden',!state.user);
  const canEdit=editableUnits().length>0;$('#planningTabButton').classList.toggle('hidden',!canEdit);$('#activityPlanningTabButton').classList.toggle('hidden',!canEdit);$('#adminTabButton').classList.toggle('hidden',adminUnits().length===0);
  $$('.app-admin-only').forEach(x=>x.classList.toggle('hidden',!state.user?.isAppAdmin));populateUnitSelectors();await updateOfflineWorkUI();
}
function updateConnectionUI(){const on=navigator.onLine;$('#connectionBadge').textContent=on?'Online':'Offline';$('#connectionBadge').className=`badge ${on?'online':'offline'}`}
async function updateOfflineWorkUI(){try{const s=await db.getOfflineWorkStatus();$('#syncButton').classList.toggle('hidden',!state.user||!s.dirtyCount);if(s.dirtyCount)$('#syncButton').textContent=`Sync Offline Work (${s.dirtyCount})`}catch{}}
async function syncOfflineWork(silent=false){if(!navigator.onLine){if(!silent)toast('Still offline. Your work remains saved on this device.','warning');return}const b=$('#syncButton');setBusy(b,true,'Syncing…');try{await db.reconnect();const r=await db.syncOfflineDrafts();if(!silent||r.synced)toast(`${r.synced} offline draft${r.synced===1?'':'s'} synchronized${r.failed?`; ${r.failed} failed`:''}.`,r.failed?'warning':'success');await updateOfflineWorkUI();if(state.planning)loadPlanningMonth();if(state.specialPlanning)loadSpecialPlanningActivity()}catch(err){toast(err.message,'error')}finally{setBusy(b,false)}}

function populateUnitSelectors(){
  const all=state.units.map(u=>`<option value="${u.id}">${esc(u.name)} (${esc(u.charter_number||'')})</option>`).join('');
  const publicCurrent=$('#publicUnitSelect').value;$('#publicUnitSelect').innerHTML=all;if(state.units.some(u=>u.id===publicCurrent))$('#publicUnitSelect').value=publicCurrent;
  $('#activityUnitFilter').innerHTML='<option value="all">All Units Statewide</option>'+all;
  populatePlanUnitSelector();populateSpecialPlanUnitSelector();
}
function populatePlanUnitSelector(){const program=$('#planProgramSelect').value||'cadet',units=editableUnits(program),cur=$('#planUnitSelect').value;$('#planUnitSelect').innerHTML=units.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');$('#planUnitSelect').value=units.some(u=>u.id===cur)?cur:preferredUnit(units);syncPlanningDefaultCheckbox()}
function populateSpecialPlanUnitSelector(){const units=editableUnits(),cur=$('#specialPlanUnitSelect').value;$('#specialPlanUnitSelect').innerHTML=units.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');$('#specialPlanUnitSelect').value=units.some(u=>u.id===cur)?cur:preferredUnit(units)}
function updateMonthButtons(){$('#publicCurrentMonth').textContent=monthLabel(state.publicDate);$('#planCurrentMonth').textContent=monthLabel(state.planDate)}
function shiftMonth(which,delta){const k=which==='public'?'publicDate':'planDate';state[k]=new Date(state[k].getFullYear(),state[k].getMonth()+delta,1);updateMonthButtons();which==='public'?renderPublicSchedule():loadPlanningMonth()}

function restorePublicDefault(){const p=JSON.parse(localStorage.getItem('capSchedule.defaultSchedule')||'null');if(p&&state.units.some(u=>u.id===p.unitId)){$('#publicUnitSelect').value=p.unitId;$('#publicProgramSelect').value=p.program||'combined';$('#publicViewSelect').value=p.view||'basic'}else if(state.units[0])$('#publicUnitSelect').value=state.units[0].id;syncPublicDefaultCheckbox()}
function savePublicDefault(){if($('#saveDefaultSchedule').checked){localStorage.setItem('capSchedule.defaultSchedule',JSON.stringify({unitId:$('#publicUnitSelect').value,program:$('#publicProgramSelect').value,view:$('#publicViewSelect').value}));toast('Default public schedule saved on this device.','success')}else{localStorage.removeItem('capSchedule.defaultSchedule');toast('Public schedule default removed.')}}
function syncPublicDefaultCheckbox(){const p=JSON.parse(localStorage.getItem('capSchedule.defaultSchedule')||'null');$('#saveDefaultSchedule').checked=!!(p&&p.unitId===$('#publicUnitSelect').value&&p.program===$('#publicProgramSelect').value)}
async function savePlanningDefault(){const unitId=$('#planUnitSelect').value;if($('#savePlanningDefault').checked){localStorage.setItem('capSchedule.editorDefaultUnit',unitId);try{await db.updateMyDefaultUnit(unitId);state.user.defaultUnitId=unitId}catch(err){toast(err.message,'warning')}toast('This is now your default editing unit.','success')}else{localStorage.removeItem('capSchedule.editorDefaultUnit');if(state.user?.defaultUnitId===unitId){try{await db.updateMyDefaultUnit(null);state.user.defaultUnitId=null}catch(err){toast(err.message,'warning')}}}syncPlanningDefaultCheckbox()}
function syncPlanningDefaultCheckbox(){const unitId=$('#planUnitSelect').value;const local=localStorage.getItem('capSchedule.editorDefaultUnit');$('#savePlanningDefault').checked=!!unitId&&(state.user?.defaultUnitId===unitId||local===unitId)}

async function openAccountDialog(){const allowed=state.user?.isAppAdmin?state.units:editableUnits();$('#accountDefaultUnit').innerHTML='<option value="">No default</option>'+allowed.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');$('#accountDefaultUnit').value=state.user?.defaultUnitId||'';$('#accountPassword').value='';$('#accountPasswordConfirm').value='';$('#accountError').textContent='';$('#accountDialog').showModal()}
async function saveAccount(e){e.preventDefault();const b=e.submitter;setBusy(b,true,'Saving…');$('#accountError').textContent='';try{const u=$('#accountDefaultUnit').value||null;await db.updateMyDefaultUnit(u);state.user.defaultUnitId=u;if(u)localStorage.setItem('capSchedule.editorDefaultUnit',u);else localStorage.removeItem('capSchedule.editorDefaultUnit');const p=$('#accountPassword').value,c=$('#accountPasswordConfirm').value;if(p||c){if(p.length<8)throw new Error('New password must be at least 8 characters.');if(p!==c)throw new Error('Passwords do not match.');await db.updatePassword(p)}$('#accountDialog').close();populatePlanUnitSelector();populateSpecialPlanUnitSelector();toast('Account settings saved.','success')}catch(err){$('#accountError').textContent=err.message}finally{setBusy(b,false)}}

async function renderPublicSchedule(){const unitId=$('#publicUnitSelect').value;if(!unitId){$('#publicSchedule').innerHTML='<div class="empty-state">No units are configured.</div>';return}$('#scheduleStatus').textContent=navigator.onLine?'Loading published schedule…':'Offline — showing cached published schedules when available.';try{const [rows,lookup]=await Promise.all([db.getPublicMonth(unitId,state.publicDate.getFullYear(),state.publicDate.getMonth()+1,$('#publicProgramSelect').value),db.getLookupData(unitId)]);state.publicRows=rows;state.publicLookup=lookup;renderPublicRows();$('#scheduleStatus').textContent=rows.length?`${rows.length} published meeting${rows.length===1?'':'s'}${navigator.onLine?'':' from offline cache'}.`:'No published schedule for this selection.'}catch(err){$('#scheduleStatus').textContent=err.message;$('#publicSchedule').innerHTML='';toast(err.message,'error')}}
function renderPublicRows(){const lookup=state.publicLookup||{groups:[]};$('#publicGroupLegend').innerHTML=(lookup.groups||[]).filter(g=>g.active!==false).map(g=>`<span class="group-chip" style="--chip-color:${esc(g.color)}"><span class="group-dot"></span>${esc(g.name)}</span>`).join('');const view=$('#publicViewSelect').value;if(!state.publicRows.length){$('#publicSchedule').innerHTML='<div class="empty-state"><h2>No published meetings</h2><p>Choose another month, schedule, or unit.</p></div>';return}if(view==='grouped')renderPublicGrouped();else if(view==='plan')renderPublicPlan();else renderPublicBasic()}
function meetingHeader(m){const theme=lookupName(state.publicLookup?.themes,m.theme_id),uniform=lookupName(state.publicLookup?.uniforms,m.uniform_id);return `<div class="meeting-card-header"><div><h3>${esc(fmtDate(m.meeting_date))}${m.is_cancelled?' — CANCELLED':''}</h3><div class="meeting-meta"><span>${esc((m.program_type||'').toUpperCase())}</span>${theme?`<span>Theme: ${esc(theme)}</span>`:''}${uniform?`<span>UOD: ${esc(uniform)}</span>`:''}${holidayLabel(m.meeting_date)?`<span>⚠ ${esc(holidayLabel(m.meeting_date))}</span>`:''}</div></div><div class="meeting-meta"><span>${niceTime(m.start_time)}–${niceTime(m.end_time)}</span></div></div>`}
function eventRow(e){const color=eventColor(e,state.publicLookup);return `<div class="event-row" style="border-left-color:${color}"><div class="event-time">${niceTime(e.start_time)}–${niceTime(e.end_time)}</div><div><div class="event-title">${esc(e.title)}</div><div class="group-chips">${groupChips(e.group_ids,state.publicLookup)}</div></div><div class="event-room">${esc(lookupName(state.publicLookup?.rooms,e.room_id)||'General / Unassigned')}</div><div class="event-instructor">${e.instructor_name?`Instructor: ${esc(e.instructor_name)}`:''}</div></div>`}
function renderPublicBasic(){$('#publicSchedule').innerHTML=state.publicRows.map(m=>`<article class="meeting-card ${m.is_cancelled?'cancelled':''}">${meetingHeader(m)}<div class="meeting-events">${m.is_cancelled?`<p>${esc(m.cancel_reason||'Meeting cancelled.')}</p>`:(m.events||[]).map(eventRow).join('')||'<p class="muted-text">No detailed activities published.</p>'}</div></article>`).join('')}
function renderPublicGrouped(){const used=new Set(state.publicRows.flatMap(m=>(m.events||[]).flatMap(e=>e.group_ids||[])));const groups=(state.publicLookup?.groups||[]).filter(g=>g.active!==false||used.has(g.id));$('#publicSchedule').innerHTML=state.publicRows.map(m=>{if(m.is_cancelled)return `<article class="meeting-card cancelled">${meetingHeader(m)}<div class="meeting-events"><p>${esc(m.cancel_reason||'Meeting cancelled.')}</p></div></article>`;const parts=[];const general=(m.events||[]).filter(e=>!e.group_ids?.length);if(general.length)parts.push(`<div class="group-section"><div class="group-section-title" style="--group-color:#7e8b99">Everyone / General</div>${general.map(eventRow).join('')}</div>`);for(const g of groups){const ev=(m.events||[]).filter(e=>e.group_ids?.includes(g.id));if(ev.length)parts.push(`<div class="group-section"><div class="group-section-title" style="--group-color:${esc(g.color)}">${esc(g.name)}</div>${ev.map(eventRow).join('')}</div>`)}return `<article class="meeting-card">${meetingHeader(m)}<div class="meeting-events">${parts.join('')||'<p class="muted-text">No detailed activities published.</p>'}</div></article>`}).join('')}
function renderPublicPlan(){$('#publicSchedule').innerHTML='';for(const m of state.publicRows){const card=document.createElement('article');card.className='public-plan-meeting';card.innerHTML=meetingHeader(m)+`<div class="planner-board"></div>`;$('#publicSchedule').appendChild(card);if(!m.is_cancelled)buildTimePlanner(card.querySelector('.planner-board'),{startMin:toMinutes(m.start_time||'18:30'),endMin:toMinutes(m.end_time||'21:00'),rooms:state.publicLookup.rooms,events:m.events||[],lookup:state.publicLookup,zoom:10,editable:false})}}

async function loadPlanningMonth(){if(!state.user)return;const unitId=$('#planUnitSelect').value,program=$('#planProgramSelect').value;if(!unitId)return;$('#plannerSaveStatus').textContent=navigator.onLine?'Loading draft…':'Opening offline draft…';try{const [p,l]=await Promise.all([db.getPlanningMonth(unitId,program,state.planDate.getFullYear(),state.planDate.getMonth()+1),db.getLookupData(unitId)]);state.planning=p;state.planLookup=l;$('#planMeetingWeekday').value=String(p.schedule.meeting_weekday??1);const ms=p.version.meetings||[];state.selectedMeetingId=ms.some(m=>m.id===state.selectedMeetingId)?state.selectedMeetingId:ms[0]?.id||null;renderPlanning();$('#plannerSaveStatus').textContent=navigator.onLine?'':'Offline edits are saved on this device until you reconnect.';await updateOfflineWorkUI()}catch(err){$('#plannerSaveStatus').textContent=err.message;toast(err.message,'error')}}
function renderPlanning(){const p=state.planning;if(!p)return;$('#draftVersionLabel').textContent=` • Version ${p.version.version_number}${p.version.offline?' • Offline Draft':''}`;const meetings=p.version.meetings||[];$('#meetingList').innerHTML=meetings.map(m=>`<button data-meeting-id="${m.id}" class="${m.id===state.selectedMeetingId?'active':''}"><strong>${esc(new Date(`${m.meeting_date}T12:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}))}</strong>${holidayLabel(m.meeting_date)?`<div class="holiday">⚠ ${esc(holidayLabel(m.meeting_date))}</div>`:''}${m.is_cancelled?'<div class="cancelled">Cancelled</div>':`<div class="muted-text small-text">${esc(lookupName(state.planLookup.themes,m.theme_id)||'Unassigned')}</div>`}</button>`).join('');$$('#meetingList button').forEach(b=>b.addEventListener('click',()=>{state.selectedMeetingId=b.dataset.meetingId;renderPlanning()}));const m=selectedMeeting();$('#plannerEmpty').classList.toggle('hidden',!!m);$('#plannerWorkspace').classList.toggle('hidden',!m);$('#meetingEditorHeader').classList.toggle('hidden',!m);if(!m){$('#requirementDashboard').innerHTML='';return}$('#meetingThemeSelect').innerHTML='<option value="">No theme</option>'+state.planLookup.themes.filter(x=>x.active!==false||x.id===m.theme_id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('#meetingUniformSelect').innerHTML='<option value="">No default</option>'+state.planLookup.uniforms.filter(x=>x.active!==false||x.id===m.uniform_id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('#meetingThemeSelect').value=m.theme_id||'';$('#meetingUniformSelect').value=m.uniform_id||'';$('#meetingStartTime').value=String(m.start_time||'18:30').slice(0,5);$('#meetingEndTime').value=String(m.end_time||'21:00').slice(0,5);$('#cancelMeetingButton').textContent=m.is_cancelled?'Restore Meeting':'Cancel Meeting';renderRequirementDashboard();renderPlanner()}
async function changePlanningWeekday(){if(!state.planning)return;try{state.planning=await db.setScheduleMeetingWeekday(state.planning,Number($('#planMeetingWeekday').value));state.selectedMeetingId=state.planning.version.meetings?.[0]?.id||null;renderPlanning();toast('Monthly meeting night updated. Existing planned exceptions were preserved.','success');await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
async function saveMeetingHeader(){const m=selectedMeeting();if(!m)return;const patch={theme_id:$('#meetingThemeSelect').value||null,uniform_id:$('#meetingUniformSelect').value||null,start_time:$('#meetingStartTime').value,end_time:$('#meetingEndTime').value};if(toMinutes(patch.end_time)<=toMinutes(patch.start_time)){toast('Meeting end must be after start.','error');return}try{Object.assign(m,await db.updateMeeting(m.id,patch,state.planning));renderRequirementDashboard();renderPlanner();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
async function toggleMeetingCancelled(){const m=selectedMeeting();if(!m)return;const cancelling=!m.is_cancelled;let reason=null;if(cancelling)reason=prompt('Cancellation reason (optional):','')||null;try{Object.assign(m,await db.updateMeeting(m.id,{is_cancelled:cancelling,cancel_reason:reason},state.planning));renderPlanning();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
function openCopyMeeting(){$('#copyMeetingDate').value=selectedMeeting()?.meeting_date||'';$('#copyMeetingDialog').showModal()}
async function copyMeeting(e){e.preventDefault();const m=selectedMeeting();if(!m)return;try{await db.copyMeeting(m.id,$('#copyMeetingDate').value,state.planning);$('#copyMeetingDialog').close();await loadPlanningMonth();toast('Meeting copied.','success')}catch(err){toast(err.message,'error')}}
function openCopyMonth(){const d=new Date(state.planDate);d.setMonth(d.getMonth()-1);$('#copySourceMonth').value=`${d.getFullYear()}-${pad(d.getMonth()+1)}`;$('#copyMonthDialog').showModal()}
async function copyMonth(e){e.preventDefault();const [y,m]=$('#copySourceMonth').value.split('-').map(Number);try{await db.copyMonth(state.planning.version.id,y,m);$('#copyMonthDialog').close();await loadPlanningMonth();toast('Month copied into this draft.','success')}catch(err){toast(err.message,'error')}}
async function publishSchedule(){if(!state.planning)return;if(!navigator.onLine){toast('Reconnect before publishing. Your offline draft is safely stored on this device.','warning');return}const b=$('#publishButton');setBusy(b,true,'Publishing…');try{await syncOfflineWork(true);await db.publishVersion(state.planning.version.id);toast('Schedule published. Previous published version remains in history.','success');await loadPlanningMonth();await renderPublicSchedule()}catch(err){toast(err.message,'error')}finally{setBusy(b,false)}}

function mergedCategoryMinutes(meetings,categoryId){let total=0;for(const m of meetings.filter(x=>!x.is_cancelled)){const intervals=(m.events||[]).filter(e=>e.category_id===categoryId).map(e=>[toMinutes(e.start_time),toMinutes(e.end_time)]).sort((a,b)=>a[0]-b[0]);let cur=null;for(const i of intervals){if(!cur)cur=[...i];else if(i[0]<=cur[1])cur[1]=Math.max(cur[1],i[1]);else{total+=cur[1]-cur[0];cur=[...i]}}if(cur)total+=cur[1]-cur[0]}return total}
function renderRequirementDashboard(){const req=(state.planLookup.requirements||[]).filter(r=>r.program_type===state.planning.schedule.program_type);if(!req.length){$('#requirementDashboard').innerHTML='';return}$('#requirementDashboard').innerHTML=req.map(r=>{const mins=mergedCategoryMinutes(state.planning.version.meetings||[],r.category_id),occ=(state.planning.version.meetings||[]).some(m=>(m.events||[]).some(e=>e.category_id===r.category_id));const met=r.occurrence_required?occ:mins>=Number(r.minimum_minutes||0);return `<div class="requirement-card ${met?'met':''}"><strong>${esc(r.name)}</strong><div class="req-value">${r.occurrence_required?(occ?'Scheduled':'Not scheduled'):`${mins} / ${r.minimum_minutes||0} minutes`}</div></div>`}).join('')}

function renderPlanner(){const m=selectedMeeting();if(!m)return;buildTimePlanner($('#plannerBoard'),{startMin:toMinutes(m.start_time||'18:30'),endMin:toMinutes(m.end_time||'21:00'),rooms:state.planLookup.rooms,events:m.events||[],lookup:state.planLookup,zoom:Number($('#planZoomSelect').value||5),editable:!m.is_cancelled,onEdit:e=>openEventDialog(e),onChange:async(e,changes)=>{try{const row=await db.saveEvent(m.id,{...e,...changes},state.planning);Object.assign(e,row);renderRequirementDashboard();renderPlanner();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}})}
function openEventDialog(event=null){const m=selectedMeeting();if(!m)return;const e=event||{};$('#eventDialogTitle').textContent=event?'Edit Scheduled Activity':'Add Scheduled Activity';$('#eventId').value=e.id||'';$('#eventTitle').value=e.title||'';$('#eventStart').value=String(e.start_time||m.start_time||'18:30').slice(0,5);$('#eventEnd').value=String(e.end_time||fromMinutes(toMinutes($('#eventStart').value)+30)).slice(0,5);$('#eventRoom').innerHTML='<option value="">General / Unassigned</option>'+state.planLookup.rooms.filter(r=>r.active!==false).map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');$('#eventRoom').value=e.room_id||'';$('#eventCategory').innerHTML='<option value="">Other / No category</option>'+state.planLookup.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#eventCategory').value=e.category_id||'';$('#eventInstructor').value=e.instructor_name||'';$('#eventUniform').innerHTML='<option value="">Use meeting UOD</option>'+state.planLookup.uniforms.filter(u=>u.active!==false).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');$('#eventUniform').value=e.uniform_override_id||'';$('#eventDescription').value=e.description||'';renderGroupChecks('#eventGroups',state.planLookup.groups,e.group_ids||[]);$('#deleteEventButton').classList.toggle('hidden',!event);$('#eventDialog').showModal()}
function renderGroupChecks(selector,groups,selected=[]){$(selector).innerHTML=(groups||[]).filter(g=>g.active!==false).map(g=>`<label class="group-check" style="--group-color:${esc(g.color)}"><input type="checkbox" value="${g.id}" ${selected.includes(g.id)?'checked':''}/><span>${esc(g.name)}</span></label>`).join('')||'<div class="muted-text">No groups have been created for this unit yet. Use Administration → Groups.</div>'}
function checkedGroups(selector){return [...document.querySelectorAll(`${selector} input:checked`)].map(x=>x.value)}
async function saveEventForm(e){e.preventDefault();const m=selectedMeeting();const start=$('#eventStart').value,end=$('#eventEnd').value;if(toMinutes(end)<=toMinutes(start)){toast('End time must be after start time.','error');return}const data={id:$('#eventId').value||null,title:$('#eventTitle').value.trim(),start_time:start,end_time:end,room_id:$('#eventRoom').value||null,category_id:$('#eventCategory').value||null,group_ids:checkedGroups('#eventGroups'),instructor_name:$('#eventInstructor').value.trim()||null,uniform_override_id:$('#eventUniform').value||null,description:$('#eventDescription').value.trim()||null};try{const row=await db.saveEvent(m.id,data,state.planning);const idx=m.events.findIndex(x=>x.id===data.id);if(idx>=0)m.events[idx]=row;else m.events.push(row);$('#eventDialog').close();renderRequirementDashboard();renderPlanner();await updateOfflineWorkUI();toast('Activity saved.','success')}catch(err){toast(err.message,'error')}}
async function deleteWeeklyEvent(){const id=$('#eventId').value;if(!id)return;if(!confirm('Delete this scheduled activity?'))return;try{await db.deleteEvent(id,state.planning);const m=selectedMeeting();m.events=m.events.filter(e=>e.id!==id);$('#eventDialog').close();renderRequirementDashboard();renderPlanner();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
async function openActivityLibrary(){const list=state.planLookup.activityLibrary||[];$('#libraryList').innerHTML=list.map(a=>`<div class="library-item"><div><strong>${esc(a.title)}</strong>${lookupName(state.planLookup.categories,a.category_id)?`<div class="muted-text small-text">${esc(lookupName(state.planLookup.categories,a.category_id))}</div>`:''}</div><button class="button secondary small" data-lib-id="${a.id}">Use</button></div>`).join('')||'<p>No library activities configured.</p>';$$('#libraryList [data-lib-id]').forEach(b=>b.addEventListener('click',()=>{const a=list.find(x=>x.id===b.dataset.libId);$('#libraryDialog').close();openEventDialog({title:a.title,category_id:a.category_id,description:a.description})}));$('#libraryDialog').showModal()}
async function openMeetingTemplates(){try{const t=await db.getMeetingTemplates(state.planning.schedule.unit_id,state.planning.schedule.program_type);$('#templateList').innerHTML=t.map(x=>`<div class="library-item"><strong>${esc(x.name)}</strong><button class="button secondary small" data-template-id="${x.id}">Apply</button></div>`).join('')||'<p class="muted-text">No templates yet.</p>';$$('#templateList [data-template-id]').forEach(b=>b.addEventListener('click',async()=>{try{await db.applyMeetingTemplate(selectedMeeting().id,b.dataset.templateId);$('#templateDialog').close();await loadPlanningMonth();toast('Template applied.','success')}catch(err){toast(err.message,'error')}}));$('#newTemplateName').value='';$('#templateDialog').showModal()}catch(err){toast(err.message,'error')}}
async function saveCurrentTemplate(e){e.preventDefault();try{await db.saveMeetingAsTemplate(selectedMeeting().id,$('#newTemplateName').value.trim());$('#templateDialog').close();toast('Meeting template saved.','success')}catch(err){toast(err.message,'error')}}

// Generic room/time planner. Weekly events use HH:MM. Special activity events use ISO datetimes transformed before calling.
function buildTimePlanner(container,{startMin,endMin,rooms,events,lookup,zoom=5,editable=false,onEdit=null,onChange=null}){
  startMin=Math.floor(startMin/5)*5;endMin=Math.ceil(endMin/5)*5;if(endMin<=startMin)endMin=startMin+60;
  const h={5:144,10:96,15:72}[zoom]||120,ppm=h/60,minor=h*(zoom/60),duration=endMin-startMin;
  const usedRooms=new Set((events||[]).map(e=>e.room_id).filter(Boolean));const roomList=[...(rooms||[]).filter(r=>r.active!==false||(!editable&&usedRooms.has(r.id)))];if((events||[]).some(e=>!e.room_id)||!roomList.length)roomList.unshift({id:'__none',name:'General / Unassigned'});
  const cols=`64px repeat(${Math.max(1,roomList.length)},220px)`;container.style.setProperty('--hour-height',`${h}px`);container.innerHTML=`<div class="planner-grid" style="min-width:${64+Math.max(1,roomList.length)*220}px"><div class="planner-header" style="grid-template-columns:${cols}"><div>Time</div>${roomList.map(r=>`<div>${esc(r.name)}</div>`).join('')}</div><div class="planner-body" style="grid-template-columns:${cols};height:${duration*ppm}px"><div class="time-column"></div>${roomList.map(r=>`<div class="room-column" data-room-id="${r.id}" style="--minor-height:${minor}px;height:${duration*ppm}px"></div>`).join('')}</div></div>`;
  const body=container.querySelector('.planner-body'),timeCol=container.querySelector('.time-column');
  for(let m=Math.ceil(startMin/60)*60;m<=endMin;m+=60){const l=document.createElement('div');l.className='time-label';l.style.top=`${(m-startMin)*ppm}px`;l.textContent=niceTime(fromMinutes(m));timeCol.appendChild(l)}
  for(const e of events||[]){const sm=toMinutes(e._display_start||e.start_time),em=toMinutes(e._display_end||e.end_time);if(em<=startMin||sm>=endMin)continue;const roomId=e.room_id||'__none';let col=container.querySelector(`.room-column[data-room-id="${CSS.escape(roomId)}"]`);if(!col)col=container.querySelector('.room-column');const block=document.createElement('div');block.className=`planner-event ${editable?'editable':''}`;block.style.setProperty('--group-color',eventColor(e,lookup));block.style.top=`${(Math.max(sm,startMin)-startMin)*ppm+2}px`;block.style.height=`${Math.max(22,(Math.min(em,endMin)-Math.max(sm,startMin))*ppm-4)}px`;block.dataset.eventId=e.id;block.innerHTML=`<div class="planner-event-title">${esc(e.title)}</div><div class="planner-event-meta">${niceTime(fromMinutes(sm))}–${niceTime(fromMinutes(em))}${e.instructor_name?` • ${esc(e.instructor_name)}`:''}</div>${editable?'<div class="resize-handle"></div>':''}`;col.appendChild(block);if(onEdit)block.addEventListener('dblclick',()=>onEdit(e));if(editable&&onChange)wirePlannerDrag(block,e,{container,body,roomList,startMin,endMin,ppm,onChange})}
}
function wirePlannerDrag(block,event,ctx){block.addEventListener('pointerdown',ev=>{if(ev.button!==0)return;const resize=!!ev.target.closest('.resize-handle');ev.preventDefault();block.setPointerCapture(ev.pointerId);block.classList.add('dragging');const y0=ev.clientY,sm=toMinutes(event._display_start||event.start_time),em=toMinutes(event._display_end||event.end_time),dur=em-sm;let lastY=ev.clientY,lastX=ev.clientX;const move=e=>{lastY=e.clientY;lastX=e.clientX};const up=async e=>{block.removeEventListener('pointermove',move);block.removeEventListener('pointerup',up);block.classList.remove('dragging');const dm=snap5((lastY-y0)/ctx.ppm);if(resize){const newEnd=Math.max(sm+5,Math.min(ctx.endMin,em+dm));await ctx.onChange(event,{_display_end:fromMinutes(newEnd),end_time:fromMinutes(newEnd)})}else{let newStart=Math.max(ctx.startMin,Math.min(ctx.endMin-dur,sm+dm)),newEnd=newStart+dur;const r=ctx.body.getBoundingClientRect(),x=lastX-r.left-64,idx=Math.max(0,Math.min(ctx.roomList.length-1,Math.floor(x/220))),room=ctx.roomList[idx];await ctx.onChange(event,{_display_start:fromMinutes(newStart),_display_end:fromMinutes(newEnd),start_time:fromMinutes(newStart),end_time:fromMinutes(newEnd),room_id:room?.id==='__none'?null:room?.id})}};block.addEventListener('pointermove',move);block.addEventListener('pointerup',up)})}

// -------------------- Public Special Activities --------------------
async function renderSpecialActivities(){try{let rows=await db.getSpecialActivities($('#activityUnitFilter').value,$('#activityRangeFilter').value,false);const mode=$('#activityRangeFilter').value,n=Date.now(),end90=n+90*86400000,year=today().getFullYear();rows=rows.filter(a=>{const s=new Date(a.starts_at).getTime(),e=new Date(a.ends_at).getTime();if(mode==='upcoming')return e>=n;if(mode==='90')return e>=n&&s<=end90;if(mode==='year')return new Date(a.starts_at).getFullYear()===year;return true});state.specialList=rows;$('#specialActivitiesList').innerHTML=rows.map(a=>`<article class="activity-card"><div class="date">${esc(fmtDateTime(a.starts_at))}</div><h3>${esc(a.title)}</h3><div class="muted-text">${esc(a.units?.name||unitName(a.unit_id))}</div>${a.location?`<p><strong>Location:</strong> ${esc(a.location)}</p>`:''}${a.description?`<p>${esc(a.description)}</p>`:''}<div class="activity-actions"><button class="button secondary small view-special-detail" data-id="${a.id}">View Detailed Schedule</button></div></article>`).join('')||'<div class="empty-state"><h2>No special activities</h2><p>No published activities match these filters.</p></div>';$$('.view-special-detail').forEach(b=>b.addEventListener('click',()=>openPublicSpecialDetail(b.dataset.id)))}catch(err){$('#specialActivitiesList').innerHTML=`<div class="empty-state">${esc(err.message)}</div>`}}
async function openPublicSpecialDetail(id){try{const detail=await db.getSpecialActivityDetail(id),lookup=await db.getLookupData(detail.activity.unit_id);$('#publicSpecialTitle').textContent=detail.activity.title;const days=activityDays(detail.activity);let html=`<div class="detail-block"><div class="detail-meta"><div><strong>Unit</strong><br>${esc(detail.activity.units?.name||unitName(detail.activity.unit_id))}</div><div><strong>When</strong><br>${esc(fmtDateTime(detail.activity.starts_at))}<br>to ${esc(fmtDateTime(detail.activity.ends_at))}</div><div><strong>Location</strong><br>${esc(detail.activity.location||'Not specified')}</div></div>${detail.activity.description?`<p>${esc(detail.activity.description)}</p>`:''}</div>`;for(const day of days){const ev=detail.events.filter(e=>dateISO(new Date(e.starts_at))===day);if(!ev.length)continue;html+=`<section class="public-special-schedule"><h3>${esc(fmtDate(day))}</h3><div class="planner-board" data-special-public-day="${day}"></div></section>`}$('#publicSpecialDetail').innerHTML=html;for(const el of $$('#publicSpecialDetail [data-special-public-day]')){const day=el.dataset.specialPublicDay,ev=detail.events.filter(e=>dateISO(new Date(e.starts_at))===day).map(e=>({...e,_display_start:localDateTimeValue(e.starts_at).slice(11,16),_display_end:localDateTimeValue(e.ends_at).slice(11,16)})),range=specialDayRange(detail,day);buildTimePlanner(el,{...range,rooms:detail.rooms,events:ev,lookup,zoom:10,editable:false})}$('#publicSpecialDialog').showModal()}catch(err){toast(err.message,'error')}}

// -------------------- Special Activity Planning --------------------
async function loadSpecialPlanningList(){if(!state.user)return;const unitId=$('#specialPlanUnitSelect').value;if(!unitId)return;try{const rows=await db.getSpecialActivities(unitId,'history',true);const cur=$('#specialPlanActivitySelect').value;$('#specialPlanActivitySelect').innerHTML='<option value="">Select an activity…</option>'+rows.map(a=>`<option value="${a.id}">${esc(a.title)} — ${esc(fmtDateShort(a.starts_at))} [${esc(a.status)}]</option>`).join('');if(rows.some(a=>a.id===cur))$('#specialPlanActivitySelect').value=cur;else if(rows.length)$('#specialPlanActivitySelect').value=rows.find(a=>a.status==='draft')?.id||rows[0].id;await loadSpecialPlanningActivity()}catch(err){toast(err.message,'error')}}
async function loadSpecialPlanningActivity(){const id=$('#specialPlanActivitySelect').value;if(!id){state.specialPlanning=null;$('#specialPlanEmpty').classList.remove('hidden');$('#specialPlanWorkspace').classList.add('hidden');return}try{state.specialPlanning=await db.getSpecialActivityDetail(id);state.specialLookup=await db.getLookupData(state.specialPlanning.activity.unit_id);state.selectedSpecialDate=activityDays(state.specialPlanning.activity).includes(state.selectedSpecialDate)?state.selectedSpecialDate:activityDays(state.specialPlanning.activity)[0];renderSpecialPlanning();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
function activityDays(activity){const start=new Date(activity.starts_at),end=new Date(activity.ends_at),out=[],d=new Date(start.getFullYear(),start.getMonth(),start.getDate());const last=new Date(end.getFullYear(),end.getMonth(),end.getDate());while(d<=last&&out.length<60){out.push(dateISO(d));d.setDate(d.getDate()+1)}return out}
function renderSpecialPlanning(){const d=state.specialPlanning;if(!d)return;$('#specialPlanEmpty').classList.add('hidden');$('#specialPlanWorkspace').classList.remove('hidden');$('#specialPlanTitle').textContent=d.activity.title;$('#specialPlanMeta').innerHTML=`${esc(fmtDateTime(d.activity.starts_at))} – ${esc(fmtDateTime(d.activity.ends_at))} • ${esc(d.activity.location||'No general location')} • <span class="status-pill ${esc(d.activity.status)}">${esc(d.activity.status)}</span>${navigator.onLine?'':' • Offline edits saved locally'}`;$('#publishSpecialButton').textContent=d.activity.status==='published'?'Published':'Publish Activity';$('#publishSpecialButton').disabled=d.activity.status==='published'&&!navigator.onLine;const days=activityDays(d.activity);$('#specialDayTabs').innerHTML=days.map(day=>`<button class="day-tab ${day===state.selectedSpecialDate?'active':''}" data-day="${day}">${esc(new Date(`${day}T12:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}))}</button>`).join('');$$('#specialDayTabs .day-tab').forEach(b=>b.addEventListener('click',()=>{state.selectedSpecialDate=b.dataset.day;renderSpecialPlanning()}));renderSpecialPlanner()}
function specialDayRange(detail,day){const ev=detail.events.filter(e=>dateISO(new Date(e.starts_at))===day);let starts=ev.map(e=>toMinutes(localDateTimeValue(e.starts_at).slice(11,16))),ends=ev.map(e=>toMinutes(localDateTimeValue(e.ends_at).slice(11,16)));const first=dateISO(new Date(detail.activity.starts_at))===day,last=dateISO(new Date(detail.activity.ends_at))===day;if(first)starts.push(toMinutes(localDateTimeValue(detail.activity.starts_at).slice(11,16)));if(last)ends.push(toMinutes(localDateTimeValue(detail.activity.ends_at).slice(11,16)));let start=starts.length?Math.max(0,Math.floor((Math.min(...starts)-30)/60)*60):8*60,end=ends.length?Math.min(24*60,Math.ceil((Math.max(...ends)+30)/60)*60):17*60;if(end-start<120)end=Math.min(24*60,start+120);return{startMin:start,endMin:end}}
function renderSpecialPlanner(){const d=state.specialPlanning;if(!d||!state.selectedSpecialDate)return;const ev=d.events.filter(e=>dateISO(new Date(e.starts_at))===state.selectedSpecialDate).map(e=>({...e,_display_start:localDateTimeValue(e.starts_at).slice(11,16),_display_end:localDateTimeValue(e.ends_at).slice(11,16)}));const range=specialDayRange(d,state.selectedSpecialDate);buildTimePlanner($('#specialPlannerBoard'),{...range,rooms:d.rooms,events:ev,lookup:state.specialLookup,zoom:Number($('#specialPlanZoomSelect').value||5),editable:true,onEdit:e=>openSpecialEventDialog(e),onChange:async(e,c)=>{try{const day=state.selectedSpecialDate;const start=`${day}T${c.start_time||e._display_start||localDateTimeValue(e.starts_at).slice(11,16)}`,end=`${day}T${c.end_time||e._display_end||localDateTimeValue(e.ends_at).slice(11,16)}`;const src=d.events.find(x=>x.id===e.id);const row=await db.saveSpecialEvent(d,{...src,room_id:c.room_id!==undefined?c.room_id:src.room_id,starts_at:start,ends_at:end});Object.assign(src,row);renderSpecialPlanner();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}})}
function openSpecialActivityDialog(a=null){const units=editableUnits();$('#specialUnit').innerHTML=units.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');$('#specialId').value=a?.id||'';$('#specialActivityDialogTitle').textContent=a?'Edit Special Activity':'New Special Activity';$('#specialUnit').value=a?.unit_id||preferredUnit(units);$('#specialStatus').value=a?.status||'draft';$('#specialTitle').value=a?.title||'';const base=new Date();base.setMinutes(Math.ceil(base.getMinutes()/5)*5,0,0);const end=new Date(base.getTime()+2*3600000);$('#specialStart').value=a?localDateTimeValue(a.starts_at):localDateTimeValue(base);$('#specialEnd').value=a?localDateTimeValue(a.ends_at):localDateTimeValue(end);$('#specialLocation').value=a?.location||'';$('#specialDescription').value=a?.description||'';$('#specialActivityError').textContent='';$('#specialActivityDialog').showModal()}
function ensureSpecialEnd(){const s=new Date($('#specialStart').value),e=new Date($('#specialEnd').value);if(!Number.isNaN(s)&&(!$('#specialEnd').value||e<=s))$('#specialEnd').value=localDateTimeValue(new Date(s.getTime()+2*3600000))}
async function saveSpecialActivityForm(e){e.preventDefault();const data={id:$('#specialId').value||null,unit_id:$('#specialUnit').value,title:$('#specialTitle').value.trim(),status:$('#specialStatus').value,starts_at:$('#specialStart').value,ends_at:$('#specialEnd').value,location:$('#specialLocation').value.trim(),description:$('#specialDescription').value.trim()};$('#specialActivityError').textContent='';try{let saved;if(!navigator.onLine&&data.status==='published'&&state.specialPlanning?.activity?.status!=='published'){throw new Error('Reconnect before publishing a new special activity. Save it as Draft while offline.')}if(!navigator.onLine&&state.specialPlanning?.activity?.id===data.id){Object.assign(state.specialPlanning.activity,{...data,starts_at:new Date(data.starts_at).toISOString(),ends_at:new Date(data.ends_at).toISOString()});await db.persistSpecialDetail(state.specialPlanning,true);saved=state.specialPlanning.activity}else saved=await db.saveSpecialActivity(data);$('#specialActivityDialog').close();$('#specialPlanUnitSelect').value=saved.unit_id;await loadSpecialPlanningList();$('#specialPlanActivitySelect').value=saved.id;await loadSpecialPlanningActivity();await renderSpecialActivities();toast('Special activity saved.','success');await updateOfflineWorkUI()}catch(err){$('#specialActivityError').textContent=err.message}}
function openSpecialEventDialog(event=null){const d=state.specialPlanning;if(!d)return;const day=event?dateISO(new Date(event.starts_at)):state.selectedSpecialDate,start=event?localDateTimeValue(event.starts_at):`${day}T08:00`,end=event?localDateTimeValue(event.ends_at):`${day}T08:30`;$('#specialEventId').value=event?.id||'';$('#specialEventTitle').value=event?.title||'';$('#specialEventStart').value=start;$('#specialEventEnd').value=end;$('#specialEventRoom').innerHTML='<option value="">General / Unassigned</option>'+d.rooms.filter(r=>r.active!==false).map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');$('#specialEventRoom').value=event?.room_id||'';$('#specialEventCategory').innerHTML='<option value="">Other / No category</option>'+state.specialLookup.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#specialEventCategory').value=event?.category_id||'';renderGroupChecks('#specialEventGroups',state.specialLookup.groups,event?.group_ids||[]);$('#specialEventInstructor').value=event?.instructor_name||'';$('#specialEventUniform').innerHTML='<option value="">No override</option>'+state.specialLookup.uniforms.filter(u=>u.active!==false).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');$('#specialEventUniform').value=event?.uniform_override_id||'';$('#specialEventDescription').value=event?.description||'';$('#deleteSpecialEventButton').classList.toggle('hidden',!event);$('#specialEventDialog').showModal()}
async function saveSpecialEventForm(e){e.preventDefault();const d=state.specialPlanning,data={id:$('#specialEventId').value||null,title:$('#specialEventTitle').value.trim(),starts_at:$('#specialEventStart').value,ends_at:$('#specialEventEnd').value,room_id:$('#specialEventRoom').value||null,category_id:$('#specialEventCategory').value||null,group_ids:checkedGroups('#specialEventGroups'),instructor_name:$('#specialEventInstructor').value.trim()||null,uniform_override_id:$('#specialEventUniform').value||null,description:$('#specialEventDescription').value.trim()||null};try{const row=await db.saveSpecialEvent(d,data),idx=d.events.findIndex(x=>x.id===data.id);if(idx>=0)d.events[idx]=row;else d.events.push(row);$('#specialEventDialog').close();state.selectedSpecialDate=dateISO(new Date(row.starts_at));renderSpecialPlanning();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
async function deleteSpecialEvent(){const id=$('#specialEventId').value;if(!id||!confirm('Delete this scheduled item?'))return;try{await db.deleteSpecialEvent(state.specialPlanning,id);state.specialPlanning.events=state.specialPlanning.events.filter(e=>e.id!==id);$('#specialEventDialog').close();renderSpecialPlanning();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
function openSpecialRooms(){renderSpecialRoomsList();$('#specialRoomsDialog').showModal()}
function renderSpecialRoomsList(){$('#specialRoomsList').innerHTML=`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Room / Location</th><th>Sort</th><th>Active</th><th></th></tr></thead><tbody>${(state.specialPlanning?.rooms||[]).map(r=>`<tr data-special-room="${r.id}"><td><input class="spr-name" value="${esc(r.name)}"></td><td><input class="spr-sort" type="number" value="${r.sort_order||100}"></td><td><input class="spr-active" type="checkbox" ${r.active!==false?'checked':''}></td><td><button class="button secondary small spr-save">Save</button></td></tr>`).join('')}</tbody></table></div>`;$$('.spr-save').forEach(b=>b.addEventListener('click',async()=>{const tr=b.closest('tr'),r=state.specialPlanning.rooms.find(x=>x.id===tr.dataset.specialRoom);try{const saved=await db.saveSpecialRoom(state.specialPlanning,{...r,name:tr.querySelector('.spr-name').value.trim(),sort_order:Number(tr.querySelector('.spr-sort').value),active:tr.querySelector('.spr-active').checked});Object.assign(r,saved);if(navigator.onLine&&!String(r.id).startsWith('offline-'))state.specialPlanning=await db.getSpecialActivityDetail(state.specialPlanning.activity.id);renderSpecialRoomsList();renderSpecialPlanner();toast('Activity room saved.','success')}catch(err){toast(err.message,'error')}}))}
async function addSpecialRoom(e){e.preventDefault();try{const r=await db.saveSpecialRoom(state.specialPlanning,{name:$('#specialRoomName').value.trim(),sort_order:Number($('#specialRoomSort').value||100),active:true});if(navigator.onLine&&!String(r.id).startsWith('offline-'))state.specialPlanning=await db.getSpecialActivityDetail(state.specialPlanning.activity.id);else if(!state.specialPlanning.rooms.some(x=>x.id===r.id))state.specialPlanning.rooms.push(r);$('#specialRoomName').value='';renderSpecialRoomsList();renderSpecialPlanner();await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
async function copyUnitRoomsToSpecial(){const existing=new Set((state.specialPlanning.rooms||[]).map(r=>r.name.toLowerCase()));const src=state.specialLookup.rooms.filter(r=>r.active!==false&&!existing.has(r.name.toLowerCase()));if(!src.length){toast('All active unit rooms are already in this activity.');return}try{for(const r of src)await db.saveSpecialRoom(state.specialPlanning,{name:r.name,sort_order:r.sort_order,active:true});if(navigator.onLine&&!String(state.specialPlanning.activity.id).startsWith('offline-'))state.specialPlanning=await db.getSpecialActivityDetail(state.specialPlanning.activity.id);renderSpecialPlanning();toast(`${src.length} unit room${src.length===1?'':'s'} copied.`, 'success');await updateOfflineWorkUI()}catch(err){toast(err.message,'error')}}
async function publishSpecialActivity(){if(!navigator.onLine){toast('Reconnect before publishing. Offline activity details remain saved locally.','warning');return}const a=state.specialPlanning.activity;try{await syncOfflineWork(true);const saved=await db.saveSpecialActivity({...a,status:'published'});state.specialPlanning=await db.getSpecialActivityDetail(saved.id);renderSpecialPlanning();renderSpecialActivities();toast('Special activity published statewide.','success')}catch(err){toast(err.message,'error')}}

// -------------------- Administration --------------------
function activateAdminPage(name){state.adminPage=name;$$('.admin-nav-item').forEach(x=>x.classList.toggle('active',x.dataset.adminPage===name));$$('.admin-page').forEach(x=>x.classList.toggle('active',x.id===`admin${name[0].toUpperCase()+name.slice(1)}Page`));renderAdmin()}
function renderAdmin(){if(state.adminPage==='users')return renderAdminUsers();if(state.adminPage==='rooms')return renderAdminRooms();if(state.adminPage==='groups')return renderAdminGroups();if(state.adminPage==='settings')return renderAdminSettings();if(state.adminPage==='requirements')return renderAdminRequirements();if(state.adminPage==='contactHours')return renderAdminContactHours();return renderAdminUnits()}
function adminSelectedUnit(el,units){const current=el.dataset.unitId;return units.some(u=>u.id===current)?current:preferredUnit(units)}
async function renderAdminUnits(){const el=$('#adminUnitsPage');if(!state.user?.isAppAdmin){el.innerHTML='<h2>Units</h2><p class="muted-text">Only an App Administrator can create or modify unit records. Unit Administrators can manage their rooms, groups, users, and uniforms.</p>';return}const units=state.units;el.innerHTML=`<div class="admin-actions"><div><h2>Units</h2><div class="muted-text">Create units and set their normal weekly meeting pattern.</div></div><button id="adminAddUnit" class="button primary">+ Add Unit</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Charter</th><th>Name</th><th>City</th><th>State</th><th>Meeting Day</th><th>Start</th><th>End</th><th>Active</th><th></th></tr></thead><tbody>${units.map(u=>unitAdminRow(u)).join('')}</tbody></table></div><div id="newUnitHost"></div>`;$$('[data-admin-unit-save]').forEach(b=>b.addEventListener('click',()=>saveAdminUnitRow(b.closest('tr'))));$('#adminAddUnit').addEventListener('click',()=>{$('#newUnitHost').innerHTML=`<div class="card" style="margin-top:14px"><h3>New Unit</h3><form id="newUnitForm" class="form-grid two-col"><div class="field"><label>Charter Number</label><input id="nuCharter" required></div><div class="field"><label>Unit Name</label><input id="nuName" required></div><div class="field"><label>City</label><input id="nuCity"></div><div class="field"><label>State</label><input id="nuState" value="MT"></div><div class="field"><label>Normal Meeting Day</label><select id="nuDay">${weekdayOptions(1)}</select></div><div class="field"><label>Start</label><input id="nuStart" type="time" value="18:30"></div><div class="field"><label>End</label><input id="nuEnd" type="time" value="21:00"></div><div><button class="button primary">Create Unit</button></div></form></div>`;$('#newUnitForm').addEventListener('submit',async e=>{e.preventDefault();try{await db.adminSaveUnit({charter_number:$('#nuCharter').value.trim(),name:$('#nuName').value.trim(),city:$('#nuCity').value.trim(),state:$('#nuState').value.trim(),meeting_weekday:Number($('#nuDay').value),default_start_time:$('#nuStart').value,default_end_time:$('#nuEnd').value,active:true});state.units=await db.getUnits();populateUnitSelectors();renderAdminUnits();toast('Unit created.','success')}catch(err){toast(err.message,'error')}})})}
function weekdayOptions(sel){return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((n,i)=>`<option value="${i}" ${Number(sel)===i?'selected':''}>${n}</option>`).join('')}
function unitAdminRow(u){return `<tr data-unit-id="${u.id}"><td><input class="u-charter" value="${esc(u.charter_number||'')}"></td><td><input class="u-name" value="${esc(u.name)}"></td><td><input class="u-city" value="${esc(u.city||'')}"></td><td><input class="u-state" value="${esc(u.state||'MT')}" style="width:60px"></td><td><select class="u-day">${weekdayOptions(u.meeting_weekday)}</select></td><td><input class="u-start" type="time" value="${String(u.default_start_time||'18:30').slice(0,5)}"></td><td><input class="u-end" type="time" value="${String(u.default_end_time||'21:00').slice(0,5)}"></td><td><input class="u-active" type="checkbox" ${u.active!==false?'checked':''}></td><td><button class="button secondary small" data-admin-unit-save>Save</button></td></tr>`}
async function saveAdminUnitRow(tr){try{await db.adminSaveUnit({id:tr.dataset.unitId,charter_number:tr.querySelector('.u-charter').value.trim(),name:tr.querySelector('.u-name').value.trim(),city:tr.querySelector('.u-city').value.trim(),state:tr.querySelector('.u-state').value.trim(),meeting_weekday:Number(tr.querySelector('.u-day').value),default_start_time:tr.querySelector('.u-start').value,default_end_time:tr.querySelector('.u-end').value,active:tr.querySelector('.u-active').checked});state.units=await db.getUnits();populateUnitSelectors();toast('Unit saved.','success')}catch(err){toast(err.message,'error')}}

async function renderAdminRooms(){const el=$('#adminRoomsPage'),units=adminUnits(),unitId=adminSelectedUnit(el,units);if(!unitId){el.innerHTML='<p>No administrable units.</p>';return}el.dataset.unitId=unitId;try{const rooms=await db.adminListRooms(unitId);el.innerHTML=`${adminUnitPicker('Rooms & Locations','Edit names and sort order. Inactivate old rooms to preserve schedule history without showing them in new planners.','adminRoomUnit',units,unitId)}<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Sort Order</th><th>Active</th><th></th></tr></thead><tbody>${rooms.map(r=>`<tr data-room-id="${r.id}"><td><input class="room-name" value="${esc(r.name)}"></td><td><input class="room-sort" type="number" value="${r.sort_order}"></td><td><label class="check-label"><input class="room-active" type="checkbox" ${r.active?'checked':''}> ${r.active?'Active':'Inactive'}</label></td><td><button class="button secondary small room-save">Save</button></td></tr>`).join('')}</tbody></table></div><form id="addRoomForm" class="inline-form card" style="margin-top:14px"><div class="field"><label>New Room / Location</label><input id="newRoomName" required></div><div class="field"><label>Sort Order</label><input id="newRoomSort" type="number" value="100"></div><button class="button primary">Add Room</button></form>`;$('#adminRoomUnit').addEventListener('change',e=>{el.dataset.unitId=e.target.value;renderAdminRooms()});$$('.room-save').forEach(b=>b.addEventListener('click',async()=>{const tr=b.closest('tr');try{await db.adminSaveRoom({id:tr.dataset.roomId,unit_id:unitId,name:tr.querySelector('.room-name').value.trim(),sort_order:Number(tr.querySelector('.room-sort').value),active:tr.querySelector('.room-active').checked});toast('Room updated.','success');renderAdminRooms()}catch(err){toast(err.message,'error')}}));$('#addRoomForm').addEventListener('submit',async e=>{e.preventDefault();try{await db.adminSaveRoom({unit_id:unitId,name:$('#newRoomName').value.trim(),sort_order:Number($('#newRoomSort').value),active:true});toast('Room added.','success');renderAdminRooms()}catch(err){toast(err.message,'error')}})}catch(err){el.innerHTML=`<p>${esc(err.message)}</p>`}}
function adminUnitPicker(title,desc,id,units,unitId){return `<div class="admin-actions"><div><h2>${esc(title)}</h2><div class="muted-text">${esc(desc)}</div></div><div class="field"><label>Unit</label><select id="${id}">${units.map(u=>`<option value="${u.id}" ${u.id===unitId?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div></div>`}

async function renderAdminGroups(){const el=$('#adminGroupsPage'),units=adminUnits(),unitId=adminSelectedUnit(el,units);if(!unitId){el.innerHTML='<p>No administrable units.</p>';return}el.dataset.unitId=unitId;try{const groups=await db.adminListGroups(unitId);el.innerHTML=`${adminUnitPicker('Schedule Groups','Groups replace free-text audience labels. Colors appear in planning and public schedules. Events can belong to multiple groups.','adminGroupUnit',units,unitId)}<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Color</th><th>Sort Order</th><th>Active</th><th></th></tr></thead><tbody>${groups.map(g=>`<tr data-group-id="${g.id}"><td><input class="group-name" value="${esc(g.name)}"></td><td><input class="group-color color-input" type="color" value="${esc(g.color)}"></td><td><input class="group-sort" type="number" value="${g.sort_order}"></td><td><input class="group-active" type="checkbox" ${g.active?'checked':''}></td><td><button class="button secondary small group-save">Save</button></td></tr>`).join('')}</tbody></table></div><form id="addGroupForm" class="inline-form card" style="margin-top:14px"><div class="field"><label>New Group</label><input id="newGroupName" placeholder="Airmen, NCO, Officer, Great Start…" required></div><div class="field"><label>Color</label><input id="newGroupColor" class="color-input" type="color" value="#2f6f9f"></div><div class="field"><label>Sort</label><input id="newGroupSort" type="number" value="100"></div><button class="button primary">Add Group</button></form>`;$('#adminGroupUnit').addEventListener('change',e=>{el.dataset.unitId=e.target.value;renderAdminGroups()});$$('.group-save').forEach(b=>b.addEventListener('click',async()=>{const tr=b.closest('tr');try{await db.adminSaveGroup({id:tr.dataset.groupId,unit_id:unitId,name:tr.querySelector('.group-name').value.trim(),color:tr.querySelector('.group-color').value,sort_order:Number(tr.querySelector('.group-sort').value),active:tr.querySelector('.group-active').checked});toast('Group updated.','success');renderAdminGroups()}catch(err){toast(err.message,'error')}}));$('#addGroupForm').addEventListener('submit',async e=>{e.preventDefault();try{await db.adminSaveGroup({unit_id:unitId,name:$('#newGroupName').value.trim(),color:$('#newGroupColor').value,sort_order:Number($('#newGroupSort').value),active:true});toast('Group added.','success');renderAdminGroups()}catch(err){toast(err.message,'error')}})}catch(err){el.innerHTML=`<p>${esc(err.message)}</p>`}}

async function renderAdminUsers(){const el=$('#adminUsersPage'),units=adminUnits(),unitId=adminSelectedUnit(el,units);if(!unitId){el.innerHTML='<p>No administrable units.</p>';return}el.dataset.unitId=unitId;try{const users=await db.adminListUsers(unitId);el.innerHTML=`${adminUnitPicker('Users & Permissions','Edit account information and unit permissions directly. New accounts use a password you set here; no invitation email is sent.','adminUserUnit',units,unitId)}<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Username / Display Name</th><th>Email</th><th>New Password<br><span class="muted-text">optional</span></th><th>Cadet</th><th>Senior</th><th>Unit Admin</th><th>App Admin</th><th></th></tr></thead><tbody>${users.map(u=>userAdminRow(u,unitId)).join('')}</tbody></table></div><div class="card" style="margin-top:16px"><h3>Create User</h3><form id="newUserForm" class="form-grid two-col"><div class="field"><label>Username / Display Name</label><input id="newUserName" required></div><div class="field"><label>Email</label><input id="newUserEmail" type="email" required></div><div class="field"><label>Initial Password</label><input id="newUserPassword" type="password" minlength="8" required></div><div class="field"><label class="check-label"><input id="newUserCadet" type="checkbox"> Edit Cadet</label><label class="check-label"><input id="newUserSenior" type="checkbox"> Edit Senior</label></div>${state.user.isAppAdmin?`<div class="field"><label class="check-label"><input id="newUserUnitAdmin" type="checkbox"> Unit Administrator</label><label class="check-label"><input id="newUserAppAdmin" type="checkbox"> App Administrator</label></div>`:''}<div><button class="button primary">Create User</button></div></form></div>`;$('#adminUserUnit').addEventListener('change',e=>{el.dataset.unitId=e.target.value;renderAdminUsers()});$$('.user-save').forEach(b=>b.addEventListener('click',()=>saveUserRow(b.closest('tr'),unitId)));$('#newUserForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;setBusy(b,true,'Creating…');try{await db.adminUpsertUser({email:$('#newUserEmail').value.trim(),display_name:$('#newUserName').value.trim(),password:$('#newUserPassword').value,unit_id:unitId,can_edit_cadet:$('#newUserCadet').checked,can_edit_senior:$('#newUserSenior').checked,is_unit_admin:$('#newUserUnitAdmin')?.checked||false,is_app_admin:$('#newUserAppAdmin')?.checked||false});toast('User created. No invitation email was sent.','success');renderAdminUsers()}catch(err){toast(err.message,'error')}finally{setBusy(b,false)}})}catch(err){el.innerHTML=`<h2>Users & Permissions</h2><p>${esc(err.message)}</p>`}}
function userAdminRow(u,unitId){const p=(u.permissions||[]).find(x=>x.unit_id===unitId)||{};const lockApp=!state.user.isAppAdmin;return `<tr data-user-id="${u.id}"><td><input class="usr-name" value="${esc(u.display_name||'')}"></td><td><input class="usr-email" type="email" value="${esc(u.email||'')}"></td><td><input class="usr-password" type="password" placeholder="Leave unchanged"></td><td><input class="usr-cadet" type="checkbox" ${p.can_edit_cadet?'checked':''}></td><td><input class="usr-senior" type="checkbox" ${p.can_edit_senior?'checked':''}></td><td><input class="usr-unitadmin" type="checkbox" ${p.is_unit_admin?'checked':''} ${lockApp?'disabled':''}></td><td><input class="usr-appadmin" type="checkbox" ${u.is_app_admin?'checked':''} ${lockApp?'disabled':''}></td><td><button class="button secondary small user-save">Save</button></td></tr>`}
async function saveUserRow(tr,unitId){const b=tr.querySelector('.user-save');setBusy(b,true,'Saving…');try{await db.adminUpsertUser({user_id:tr.dataset.userId,email:tr.querySelector('.usr-email').value.trim(),display_name:tr.querySelector('.usr-name').value.trim(),password:tr.querySelector('.usr-password').value,unit_id:unitId,can_edit_cadet:tr.querySelector('.usr-cadet').checked,can_edit_senior:tr.querySelector('.usr-senior').checked,is_unit_admin:tr.querySelector('.usr-unitadmin').checked,is_app_admin:tr.querySelector('.usr-appadmin').checked});toast('User and permissions updated.','success');renderAdminUsers()}catch(err){toast(err.message,'error')}finally{setBusy(b,false)}}

async function renderAdminSettings(){const el=$('#adminSettingsPage'),units=adminUnits(),unitId=adminSelectedUnit(el,units);if(!unitId){el.innerHTML='<p>No administrable units.</p>';return}el.dataset.unitId=unitId;try{const s=await db.adminGetSettings(unitId),app=state.user.isAppAdmin;el.innerHTML=`${adminUnitPicker('Schedule Settings',app?'App Administrators can edit meeting themes and the activity library. Activity-library durations are not used; each unit sets actual times when scheduling.':'Unit Administrators can manage local uniform choices. Meeting Themes and Activity Library are controlled by the App Administrator.','adminSettingsUnit',units,unitId)}<div class="settings-grid">${app?`<div class="card"><h3>Meeting Themes</h3>${settingsThemeTable(s.themes)}<form id="addThemeForm" class="inline-form"><input id="newThemeName" placeholder="New theme" required><select id="newThemeScope"><option value="statewide">Statewide</option><option value="unit">This unit only</option></select><button class="button secondary small">Add</button></form></div>`:`<div class="card"><h3>Meeting Themes</h3>${s.themes.filter(x=>x.active!==false).map(x=>`<div>${esc(x.name)}</div>`).join('')}</div>`}<div class="card"><h3>Uniforms</h3>${settingsUniformTable(s.uniforms,app)}<form id="addUniformForm" class="inline-form"><input id="newUniformName" placeholder="New unit uniform" required><button class="button secondary small">Add</button></form></div>${app?`<div class="card"><h3>Activity Library</h3><p class="help-text">Library entries provide titles/categories/notes only. Time is chosen when an activity is placed on a schedule.</p>${settingsLibraryTable(s.activityLibrary,s.categories)}<form id="addLibraryForm" class="form-grid"><div class="field"><label>Activity Name</label><input id="newLibTitle" required></div><div class="field"><label>Category</label><select id="newLibCategory"><option value="">Other / None</option>${s.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Scope</label><select id="newLibScope"><option value="statewide">Statewide</option><option value="unit">This unit only</option></select></div><button class="button secondary small">Add Activity</button></form></div>`:`<div class="card"><h3>Activity Library</h3>${s.activityLibrary.filter(x=>x.active!==false).map(x=>`<div>${esc(x.title)}</div>`).join('')}</div>`}</div>`;$('#adminSettingsUnit').addEventListener('change',e=>{el.dataset.unitId=e.target.value;renderAdminSettings()});if(app){$$('.theme-save').forEach(b=>b.addEventListener('click',()=>saveThemeRow(b.closest('[data-theme-id]'))));$$('.lib-save').forEach(b=>b.addEventListener('click',()=>saveLibraryRow(b.closest('[data-lib-id]'),unitId,s.categories)));$('#addThemeForm').addEventListener('submit',async e=>{e.preventDefault();try{await db.adminSaveTheme({unit_id:$('#newThemeScope').value==='unit'?unitId:null,name:$('#newThemeName').value.trim(),active:true});renderAdminSettings()}catch(err){toast(err.message,'error')}});$('#addLibraryForm').addEventListener('submit',async e=>{e.preventDefault();try{await db.adminSaveLibraryActivity({scope:$('#newLibScope').value,unit_id:unitId,title:$('#newLibTitle').value.trim(),category_id:$('#newLibCategory').value||null,active:true});renderAdminSettings()}catch(err){toast(err.message,'error')}})}$$('.uniform-save').forEach(b=>b.addEventListener('click',()=>saveUniformRow(b.closest('[data-uniform-id]'))));$('#addUniformForm').addEventListener('submit',async e=>{e.preventDefault();try{await db.adminSaveUniform({unit_id:unitId,name:$('#newUniformName').value.trim(),active:true});renderAdminSettings()}catch(err){toast(err.message,'error')}})}catch(err){el.innerHTML=`<p>${esc(err.message)}</p>`}}
function settingsThemeTable(rows){return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Scope</th><th>Active</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr data-theme-id="${x.id}" data-unit-id="${x.unit_id||''}"><td><input class="theme-name" value="${esc(x.name)}"></td><td>${x.unit_id?'Unit':'Statewide'}</td><td><input class="theme-active" type="checkbox" ${x.active!==false?'checked':''}></td><td><button class="button secondary small theme-save">Save</button></td></tr>`).join('')}</tbody></table></div>`}
async function saveThemeRow(tr){try{await db.adminSaveTheme({id:tr.dataset.themeId,unit_id:tr.dataset.unitId||null,name:tr.querySelector('.theme-name').value.trim(),active:tr.querySelector('.theme-active').checked});toast('Theme updated.','success');renderAdminSettings()}catch(err){toast(err.message,'error')}}
function settingsUniformTable(rows,app){return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Scope</th><th>Active</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr data-uniform-id="${x.id}" data-unit-id="${x.unit_id||''}"><td><input class="uniform-name" value="${esc(x.name)}"></td><td>${x.unit_id?'Unit':'Statewide'}</td><td><input class="uniform-active" type="checkbox" ${x.active!==false?'checked':''}></td><td><button class="button secondary small uniform-save" ${!app&&!x.unit_id?'disabled title="Statewide uniforms require App Administrator"':''}>Save</button></td></tr>`).join('')}</tbody></table></div>`}
async function saveUniformRow(tr){try{await db.adminSaveUniform({id:tr.dataset.uniformId,unit_id:tr.dataset.unitId||null,name:tr.querySelector('.uniform-name').value.trim(),active:tr.querySelector('.uniform-active').checked});toast('Uniform updated.','success');renderAdminSettings()}catch(err){toast(err.message,'error')}}
function settingsLibraryTable(rows,cats){return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Activity</th><th>Category</th><th>Scope</th><th>Active</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr data-lib-id="${x.id}" data-unit-id="${x.unit_id||''}" data-scope="${esc(x.scope)}"><td><input class="lib-title" value="${esc(x.title)}"></td><td><select class="lib-cat"><option value="">Other</option>${cats.map(c=>`<option value="${c.id}" ${c.id===x.category_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></td><td>${x.scope==='statewide'?'Statewide':'Unit'}</td><td><input class="lib-active" type="checkbox" ${x.active!==false?'checked':''}></td><td><button class="button secondary small lib-save">Save</button></td></tr>`).join('')}</tbody></table></div>`}
async function saveLibraryRow(tr,unitId){try{await db.adminSaveLibraryActivity({id:tr.dataset.libId,scope:tr.dataset.scope,unit_id:tr.dataset.unitId||unitId,title:tr.querySelector('.lib-title').value.trim(),category_id:tr.querySelector('.lib-cat').value||null,active:tr.querySelector('.lib-active').checked});toast('Activity library updated.','success');renderAdminSettings()}catch(err){toast(err.message,'error')}}

async function renderAdminRequirements(){const el=$('#adminRequirementsPage');if(!state.user?.isAppAdmin){el.innerHTML='';return}const unitId=preferredUnit(state.units)||state.units[0]?.id;if(!unitId){el.innerHTML='<p>No units configured.</p>';return}try{const look=await db.getLookupData(unitId);el.innerHTML=`<h2>CAP Monthly Content Requirements</h2><p class="muted-text">These values drive the live planning dashboard and Contact Hours report.</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Program</th><th>Requirement</th><th>Category</th><th>Minimum Minutes</th><th>Occurrence Only</th><th></th></tr></thead><tbody>${look.requirements.map(r=>`<tr data-req-id="${r.id}"><td>${esc(r.program_type)}</td><td>${esc(r.name)}</td><td>${esc(lookupName(look.categories,r.category_id))}</td><td><input class="req-min" type="number" min="0" step="5" value="${r.minimum_minutes??''}"></td><td><input class="req-occ" type="checkbox" ${r.occurrence_required?'checked':''}></td><td><button class="button secondary small save-req">Save</button></td></tr>`).join('')}</tbody></table></div>`;$$('.save-req').forEach(b=>b.addEventListener('click',async()=>{const tr=b.closest('tr');try{const occ=tr.querySelector('.req-occ').checked;await db.adminUpdateRequirement(tr.dataset.reqId,{minimum_minutes:occ?null:Number(tr.querySelector('.req-min').value||0),occurrence_required:occ});toast('Requirement updated.','success');renderAdminRequirements()}catch(err){toast(err.message,'error')}}))}catch(err){el.innerHTML=`<p>${esc(err.message)}</p>`}}
async function renderAdminContactHours(){const el=$('#adminContactHoursPage'),units=adminUnits();if(!units.length){el.innerHTML='';return}const app=state.user?.isAppAdmin;let unitId=el.dataset.unitId??preferredUnit(units);if(!app&&!units.some(u=>u.id===unitId))unitId=units[0]?.id||'';try{const rows=await db.adminGetContactHours(app?(unitId||null):unitId);el.innerHTML=`<div class="admin-actions"><div><h2>Contact Hours Compliance</h2><div class="muted-text">Published schedules are checked against the configured monthly content goals. Parallel group classes count time once, not once per room.</div></div><div class="field"><label>Unit</label><select id="contactUnit">${app?'<option value="">All Units</option>':''}${units.map(u=>`<option value="${u.id}" ${u.id===unitId?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Month</th><th>Unit</th><th>Program</th><th>Published</th><th>Requirements</th><th>Result</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(new Date(r.year,r.month-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'}))}</td><td>${esc(r.unit_name)}</td><td>${esc(r.program_type)}</td><td>${r.published_at?esc(new Date(r.published_at).toLocaleDateString()):''}</td><td>${(r.requirements||[]).map(q=>`<div>${esc(q.name)}: ${q.occurrence_required?(q.occurrences?'Scheduled':'Missing'):`${q.scheduled_minutes}/${q.minimum_minutes} min`} ${q.met?'✓':'✕'}</div>`).join('')}</td><td><span class="contact-result ${r.met?'met':'missed'}">${r.met?'Goal Met':'Needs Attention'}</span></td></tr>`).join('')}</tbody></table></div>`;$('#contactUnit').addEventListener('change',e=>{el.dataset.unitId=e.target.value;renderAdminContactHours()})}catch(err){el.innerHTML=`<h2>Contact Hours Compliance</h2><p>${esc(err.message)}</p>`}}

// -------------------- PWA install --------------------
function registerPWA(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(err=>console.warn('Service worker registration failed',err));if(window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone){$('#installButton').textContent='Installed';$('#installButton').disabled=true}}
async function installApp(){if(state.installPrompt){state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;return}const ua=navigator.userAgent.toLowerCase();let text;if(/iphone|ipad|ipod/.test(ua))text='<p>On iPhone/iPad: open CAP Schedule in <strong>Safari</strong>, tap the <strong>Share</strong> button, choose <strong>Add to Home Screen</strong>, then confirm.</p>';else if(/android/.test(ua))text='<p>On Android: open the browser menu (⋮) and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>. If Chrome/Edge has determined the app is installable, this CAP Schedule button will also show the native install prompt.</p>';else text='<p>On Chrome or Edge desktop: use the install icon in the address bar or open the browser menu and choose <strong>Install CAP Schedule</strong>. If the browser offers the native prompt, this button will launch it.</p>';text+='<p class="help-text">After installation it opens in its own app window. Published schedules are cached for offline viewing, and signed-in editors can work on cached/new drafts offline.</p>';$('#installInstructions').innerHTML=text;$('#installDialog').showModal()}

init().catch(err=>{console.error(err);toast(err.message||String(err),'error')});
